import java.util.*;

public class Main {
    static final long MOD = 1000000007;
    static int MAX = 1000005;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long totalProduct = 1;
        int P = sc.nextInt();
        int K = sc.nextInt();

        if (K == 0) {
            for (int i = 1; i < P; i++) {
                totalProduct = (totalProduct * P) % MOD;
            }
            System.out.println(totalProduct);
            return;
        }

        int[] cycle = new int[P + 1];
        int[] mark = new int[P + 1];
        List<Integer> cycleLengths = new ArrayList<>();

        for (int i = 1; i < P; i++) {
            if (mark[i] == 0) {
                long current = i;
                int length = 0;
                while (mark[(int) current] == 0) {
                    mark[(int) current] = 1;
                    current = (long) K * current % P;
                    length++;
                }
                cycle[length]++;
                cycleLengths.add(length);
            }
        }

        for (int length : cycleLengths) {
            long val = (long) length * cycle[length] % MOD;
            totalProduct = (totalProduct * (val + 1)) % MOD;
        }

        if (K == 1) {
            totalProduct = (totalProduct * P) % MOD;
        }

        System.out.println(totalProduct);
    }
}
